@startuml

class Customer {
  + name : string
  + address : string
}

class Account {
  + balance : double
}

class SavingsAccount extends Account {
  + interestRate : double
}

class InvestmentAccount extends Account {}

class StockOrder {
  + quantity : int
  + price : double
  + ticker : string
  + commission : double
}

class Stock {}

Customer "1" -- "*" Account : owns
Account "1" -- "*" StockOrder : executes
StockOrder "1" -- "1" Stock : involves

@enduml

